import LeagueTable from "@/app/(protected)/profile/components/leagueWrapper";

interface PageProps {
  params: Promise<{ league: string }>; // dynamic route
}

// Server component
export default async function TheProfile({ params }: PageProps) {
  const { league } = await params; // unwrap the promise
  return <LeagueTable league={league} />; // pass to client component
}
